const nodesById = new Map(PUBLISHED_NODES.map(node => [node.id, node]));
const firstPassById = new Map(firstPass.issues.map(row => [row.nodeId, row]));
const reviewIds = firstPass.issues.map(row => row.nodeId);
const prohibitedRoles = new Set(['peer_calibration', 'reviewed_contract_factors', 'vector_exclusion', 'operational_lineage', 'unscored_context']);
const axes = values => Object.fromEntries(['severity', 'reach', 'persistence'].map((key, index) => [key, values[index]]));
const clamp = value => Math.max(0, Math.min(4, value));
const digest = value => createHash('sha256').update(JSON.stringify(value)).digest('hex');
const gradeRankForScore = value => value < 2.8 ? 0 : value < 4.6 ? 1 : value < 6.4 ? 2 : value < 8.2 ? 3 : 4;

function flatten(value, path = '', role = '', unit = '', output = []) {
  if (Array.isArray(value)) {
    value.forEach((item, index) => flatten(item, `${path}[${index}]`, role, unit, output));
  } else if (value && typeof value === 'object') {
    const localUnit = typeof value.unit === 'string' ? value.unit : unit;
    for (const [key, child] of Object.entries(value)) flatten(child, path ? `${path}.${key}` : key, role, localUnit, output);
  } else if (typeof value === 'number' && Number.isFinite(value)) {
    output.push({ path: path.toLowerCase(), role, value, unit: String(unit).toLowerCase() });
  }
  return output;
}

function evidenceFacts(record) {
  return record.evidenceAudit.observations
    .filter(observation => !prohibitedRoles.has(observation.role) && observation.role !== 'source_snapshot' && observation.role !== 'source_snapshots')
    .flatMap(observation => flatten(observation.value, observation.role, observation.role));
}

function scaledCount(fact) {
  const label = `${fact.path} ${fact.unit}`;
  if (/percent|pct|share|ratio|rate/.test(label)) return null;
  if (/billion/.test(label)) return fact.value * 1e9;
  if (/million/.test(label)) return fact.value * 1e6;
  if (/thousand/.test(label)) return fact.value * 1e3;
  return fact.value;
}

function textFor(node, record, dimension) {
  const impact = dimension === 'human' ? node.humanImpact : node.planetImpact;
  return [node.name, node.description, impact?.summary, ...(impact?.domains ?? []), ...(impact?.consequences ?? []),
    ...record.evidenceAudit.observations.filter(observation => !prohibitedRoles.has(observation.role)).map(observation => `${observation.role} ${JSON.stringify(observation.value)}`)]
    .filter(Boolean).join(' ').toLowerCase();
}

const directDomainOverrides = new Map([
  ['acid_rain_deposition', ['human', 'ecosystem']],
  ['heavy_metal_bioaccumulation', ['human', 'ecosystem']],
  ['lightning_fire_weather', ['human', 'ecosystem']],
  ['particulate_soot_levels', ['human', 'ecosystem']],
]);

function applicability(node, record) {
  if (directDomainOverrides.has(node.id)) return directDomainOverrides.get(node.id);
  const human = textFor(node, record, 'human');
  const ecosystem = textFor(node, record, 'ecosystem');
  const humanNone = /no direct human outcome established|no direct human consequence/.test(human);
  const ecosystemNone = /no direct earth-system outcome established|no direct planetary consequence/.test(ecosystem);
  if (humanNone && !ecosystemNone) return ['ecosystem'];
  if (ecosystemNone && !humanNone) return ['human'];
  return ['human', 'ecosystem'];
}

function range(central, direct = false, direction = 'both') {
  if (direct) return { lower: central, central, upper: central, sourceAnchored: true };
  return {
    lower: direction === 'up' ? central : clamp(central - 1),
    central,
    upper: direction === 'down' ? central : clamp(central + 1),
    sourceAnchored: false,
  };
}

function peopleCount(facts) {
  const candidates = facts.filter(fact => {
    const label = `${fact.path} ${fact.unit}`;
    return /people|population|persons|deaths|fatalities|displaced|patients|cases|lacking|affected|exposed|workers|residents|households|customers|users/.test(label)
      && !/country_count|state_count|city_count|district_count|site_count|observation|year|duration|period|share|percent|pct|rate|ratio|anchor|denominator|context|unscored|excluded/.test(label);
  }).map(scaledCount).filter(value => Number.isFinite(value) && value > 0);
  return candidates.length ? Math.max(...candidates) : null;
}

function globalPopulationShare(facts) {
  const candidates = facts.filter(fact => /global_population.*(percent|pct)|population.*global.*(percent|pct)/.test(fact.path));
  return candidates.length ? Math.max(...candidates.map(fact => fact.value)) : null;
}

function deathCount(facts) {
  const candidates = facts.filter(fact => /death|fatalit|mortality/.test(`${fact.path} ${fact.unit}`)
    && !/rate|fraction|percent|pct|share|anchor|year|context|unscored|excluded/.test(`${fact.path} ${fact.unit}`))
    .map(scaledCount).filter(value => Number.isFinite(value) && value > 0);
  return candidates.length ? Math.max(...candidates) : null;
}

function peopleSeverity(node, record, facts) {
  const text = textFor(node, record, 'human');
  const deaths = deathCount(facts);
  if (deaths >= 100000 || (/mortality|fatalit|premature death/.test(node.name.toLowerCase()) && deaths > 0)) {
    return { ...range(4, true), basis: `${deaths.toLocaleString('en-US')} source-reported or modelled deaths place the terminal consequence at level 4.` };
  }
  if (deaths >= 1000) return { ...range(3, true), basis: `${deaths.toLocaleString('en-US')} deaths support severe current consequences at level 3.` };
  if (deaths > 0) return { ...range(2, false, 'up'), basis: `Reported fatalities establish material harm, while their scale does not independently meet the level-4 anchor.` };
  if (/loss of basic survival needs|food insecurity|water insecurity|starvation/.test(text)) return { ...range(4, false, 'down'), basis: 'The documented pathway can remove a basic survival need at scale.' };
  if (/severe illness|hospital|major displacement|prolonged loss|service failure|outage|relocation|disease outbreak|injur/.test(text)) return { ...range(3), basis: 'The evidence describes severe illness, displacement, injury or prolonged essential-service loss.' };
  if (/illness|economic loss|material loss|displacement|service interruption|damage|shortage|cost|livelihood|risk|exposure/.test(text)) return { ...range(2), basis: 'The evidence supports material illness, loss, displacement, service interruption or economic damage.' };
  return { ...range(1), basis: 'The evidence establishes inconvenience or exposure but no stronger terminal human consequence.' };
}

function peopleReach(node, facts) {
  const count = peopleCount(facts);
  if (count != null) {
    const level = count >= 100e6 ? 4 : count >= 1e6 ? 3 : count >= 10000 ? 2 : count > 0 ? 1 : 0;
    return { ...range(level, true), basis: `The largest compatible source count is ${Math.round(count).toLocaleString('en-US')} people.` };
  }
  const share = globalPopulationShare(facts);
  if (share != null) {
    const level = share >= 1.25 ? 4 : share >= 0.0125 ? 3 : share > 0 ? 2 : 0;
    return { ...range(level, false, 'up'), basis: `A global population share of ${share}% is converted only to the fixed reach anchor, with uncertainty retained.` };
  }
  const level = node.context?.reach === 'global' ? 3 : node.context?.reach === 'regional' ? 2 : 1;
  return { ...range(level), basis: `No compatible person count is present; the authored ${node.context?.reach ?? 'unspecified'} reach supports a structured level ${level}.` };
}

function durationYears(facts) {
  const candidates = facts.filter(fact => /(?:recovery.*year|impact.*duration.*year|consequence.*duration.*year|elevated.*(?:incidence|impact|effect).*duration.*year|measured_(?:effect|geochemical_signature)_persistence_years)/.test(fact.path)
      && !/observation|observed|assessment|comparison|record|monitor|window|start|end|anchor|latest|reference|count|period|context|unscored|excluded/.test(fact.path))
    .map(fact => fact.value).filter(value => value >= 0 && value <= 500);
  return candidates.length ? Math.max(...candidates) : null;
}

function persistence(node, record, facts, dimension) {
  const text = textFor(node, record, dimension);
  if (dimension === 'human' && deathCount(facts) > 0) {
    return { ...range(4, true), basis: 'The source reports attributable deaths, which are permanent terminal consequences.' };
  }
  if (/documented extinction|irreversible loss|permanent disability/.test(text)) {
    return { ...range(4, true), basis: 'The evidence explicitly documents an irreversible, permanent or lifelong terminal consequence.' };
  }
  const years = durationYears(facts);
  if (years != null) {
    const level = dimension === 'human'
      ? years > 10 ? 4 : years >= 1 ? 3 : years >= 1 / 12 ? 2 : years > 0 ? 1 : 0
      : years > 50 ? 4 : years >= 10 ? 3 : years >= 1 ? 2 : years > 0 ? 1 : 0;
    return { ...range(level, true), basis: `The source documents ${years} years of duration or recovery time.` };
  }
  const impact = dimension === 'human' ? node.humanImpact : node.planetImpact;
  const horizon = impact?.timeHorizon;
  if (['long_term', 'chronic_with_abrupt_risk'].includes(horizon) || /centur|long-lived/.test(text)) return { ...range(4, false, 'down'), basis: 'The authored evidence describes consequences persisting beyond a decade.' };
  if (/chronic|persistent|multi-year/.test(text) || node.context?.speed === 'slow') return { ...range(3), basis: 'The condition is chronic or slow to reverse, supporting a structured one-to-fifty-year judgment.' };
  if (node.context?.speed === 'medium') return { ...range(2), basis: 'The condition and recovery are neither event-limited nor established as multi-decade.' };
  return { ...range(1), basis: 'The evidence describes an event-scale or rapidly changing condition.' };
}

function relevantNaturePercent(facts) {
  const preferred = facts.filter(fact => /median.*(decline|loss|mortality).*pct/.test(fact.path));
  const candidates = preferred.length ? preferred : facts.filter(fact =>
    /decline.*(percent|pct)|loss.*(percent|pct)|degrad.*(percent|pct)|mortality.*(percent|pct)|not_free_flowing.*pct|fragmented.*pct|intactness.*(percent|pct)|threatened.*(percent|pct)/.test(fact.path)
    && !/economic|cost|price|gdp|anchor|change_percentage_points|context|unscored|excluded/.test(fact.path));
  return candidates.length ? Math.max(...candidates.map(fact => fact.value).filter(value => value >= 0 && value <= 100)) : null;
}

const incompatibleNatureSeverityPercentageNodes = new Set([
  'insect_biomass_decline',
  'trophic_cascade_collapses',
  'genetic_diversity_bottlenecks',
]);

function natureSeverity(node, record, facts) {
  const text = textFor(node, record, 'ecosystem');
  const percent = incompatibleNatureSeverityPercentageNodes.has(node.id) ? null : relevantNaturePercent(facts);
  const percentageCaveat = percent == null
    ? ''
    : ` A source reports ${percent}%, but the generic review does not use it as severity until its denominator is shown to measure condition loss within an affected ecosystem rather than reach, trend, pressure or study coverage.`;
  if (/habitat loss|biodiversity loss|degradation|dead zone|hypoxi|bleach|acidification|pollution|erosion|depletion|dieback|mortality|fragment/.test(text)) {
    return { ...range(3), basis: `The evidence supports substantial habitat, population or ecosystem-condition loss.${percentageCaveat}` };
  }
  if (/stress|decline|shift|disruption|exposure|risk|damage|warming|loss/.test(text)) {
    return { ...range(2), basis: `The evidence supports ecological stress or change without a quantified collapse-equivalent loss.${percentageCaveat}` };
  }
  return { ...range(1), basis: `The evidence establishes an ecological pressure but no stronger condition-loss anchor.${percentageCaveat}` };
}

function natureExtent(node, facts) {
  const candidates = facts.filter(fact => fact.role === 'extent'
    && /(share|percent|pct)/.test(fact.path)
    && !/year|change|anchor|normalized|sector|context|unscored|excluded/.test(fact.path)
    && fact.value >= 0 && fact.value <= 100);
  if (candidates.length) {
    const selected = [...candidates].sort((a, b) => b.value - a.value)[0];
    const percent = selected.value;
    const rawLevel = percent >= 50 ? 4 : percent >= 10 ? 3 : percent >= 1 ? 2 : percent > 0 ? 1 : 0;
    if (/countr/.test(selected.path)) {
      const central = clamp(rawLevel - 1);
      return { lower: clamp(central - 1), central, upper: rawLevel, basis: `The source reports ${percent}% of countries with a documented condition. Country coverage is only a proxy for ecosystem-distribution extent.` };
    }
    return { ...range(rawLevel, false, 'up'), basis: `The source reports ${percent}% spatial extent; denominator compatibility is retained in the upper bound.` };
  }
  const level = node.context?.reach === 'global' ? 3 : node.context?.reach === 'regional' ? 2 : 1;
  return { ...range(level), basis: `No compatible ecosystem-distribution percentage is present; the authored ${node.context?.reach ?? 'unspecified'} reach supports a structured level ${level}.` };
}

function nearestAnalogues(node, records) {
  if (node.id === 'tundra_methane_outgassing') return ['methane', 'permafrost_thaw'];
  const tokens = new Set(`${node.name} ${node.description}`.toLowerCase().match(/[a-z]{4,}/g) ?? []);
  const candidates = PUBLISHED_NODES.filter(other => other.id !== node.id && other.node_kind !== 'response'
    && other.sphere === node.sphere && records[other.id]?.evidenceAudit?.previousRoute !== 'modeled');
  return candidates.map(other => {
    const otherTokens = new Set(`${other.name} ${other.description}`.toLowerCase().match(/[a-z]{4,}/g) ?? []);
    const overlap = [...tokens].filter(token => otherTokens.has(token)).length;
    return { id: other.id, overlap };
  }).sort((a, b) => b.overlap - a.overlap || a.id.localeCompare(b.id)).slice(0, 2).map(item => item.id);
}

