function causalAllocationFor(nodeId) {
  const aggregateNodeIds = unresolvedEmissionSources.get(nodeId);
  if (!aggregateNodeIds) return null;
  return {
    role: 'emission_source',
    aggregateNodeIds,
    attributionStatus: 'unresolved',
    researchStatus: 'source_inventory_screened_terminal_consequence_model_missing',
    researchRecord: 'artifacts/tulip-calibration-2026-09-22/internal-emission-source-allocation.json',
    inheritsAggregateScore: false,
    counterfactual: `Compare current terminal harm with the same climate and socioeconomic system after removing the emissions attributable to ${nodeId}, without assuming another source replaces them.`,
    aggregationDenominator: 'A compatible source share of anthropogenic greenhouse-gas emissions over the same geography and current assessment window, followed by a source-specific marginal climate-response and terminal-consequence model.',
    overlapExclusions: [
      `Do not copy or multiply the ${aggregateNodeIds.join(' or ')} score.`,
      'Do not add downstream warming, hazard and endpoint-node scores to the source candidate.',
      'Do not treat annual emissions tonnage as a direct severity, reach or persistence value.',
    ],
    limitations: 'The current evidence does not yet provide a compatible source-removal counterfactual through climate response to non-overlapping terminal consequences. The numerical candidate therefore remains family-calibrated at confidence D.',
  };
}

