function groundwaterIrrigationPressureOverride(nodeId) {
  const a = groundwaterIrrigationReference.assessment;
  const sourceId = groundwaterIrrigationReference.source.id;
  const isOverdraft = nodeId === 'aquifer_overdraft';
  const isAgricultural = nodeId === 'agricultural_groundwater_withdrawal';
  const isMunicipal = nodeId === 'municipal_groundwater_withdrawal';
  const label = isOverdraft ? 'aquifer overdraft' : isAgricultural ? 'agricultural groundwater withdrawal' : isMunicipal ? 'municipal groundwater withdrawal' : 'irrigation water inefficiency';
  const evidenceYear = isOverdraft || isAgricultural ? a.depletion_assessment_year : a.assessment_year;
  const startYear = isOverdraft ? a.depletion_period_start_year : isAgricultural ? a.agricultural_groundwater_use_acceleration_start_year : a.global_freshwater_demand_growth_start_year;
  const directFact = isOverdraft
    ? `UNESCO reports global aggregated groundwater depletion of ${a.global_groundwater_depletion_range_km3_per_year[0]}–${a.global_groundwater_depletion_range_km3_per_year[1]} km³ per year, about ${a.global_groundwater_depletion_share_of_withdrawals_range_pct[0]}–${a.global_groundwater_depletion_share_of_withdrawals_range_pct[1]}% of withdrawals.`
    : isAgricultural
      ? `Agriculture accounts for ${a.groundwater_abstraction_by_sector_pct.agriculture}% of global groundwater abstraction and groundwater serves ${a.irrigated_land_serviced_by_groundwater_pct}% of irrigated land.`
      : isMunicipal
        ? `Domestic use accounts for ${a.groundwater_abstraction_by_sector_pct.domestic}% of groundwater abstraction, while groundwater supplies about ${a.global_urban_population_supplied_by_groundwater_pct}% of the global urban population.`
        : `FAO reports at least ${a.irrigation_withdrawal_loss_lower_bound_pct}% of irrigation withdrawals as conveyance, percolation or runoff loss, while warning that part can return to rivers or aquifers.`;
  return {
    domains: isOverdraft ? ['human', 'ecosystem'] : ['ecosystem'], confidence: 'C', latestCompatibleEvidenceYear: evidenceYear,
    currentWindow: {
      start: startYear, end: evidenceYear, coverageStatus: 'partial', summaryMethod: isOverdraft ? 'annualized_flow' : 'period_prevalence',
      coverageNote: 'The global assessment combines source-declared rates and shares rather than a complete annual, same-boundary consequence panel. Missing countries and years are not filled with zero.',
      isLatestAvailable: true, recencyCheckedOn: '2026-09-26',
      recencyRationale: `The ${evidenceYear} UNESCO/FAO assessment is the newest compatible global source in the registry for ${label}. Its dependence and coverage figures remain exposure or pressure, not current shortage or ecosystem loss.`,
      normalization: isOverdraft
        ? 'Use the global depletion range as physical aquifer-state evidence. Keep domestic dependence, sector shares, assessment duration and global scope outside terminal severity, reach and persistence.'
        : isAgricultural
          ? 'Use agriculture share of abstraction as sector pressure. Do not allocate the global depletion range to agriculture or treat irrigated-land dependence as crop loss.'
          : isMunicipal
            ? 'Use domestic abstraction share as sector pressure. Do not treat urban population supplied by groundwater as people experiencing shortage.'
            : 'Use the reported irrigation-loss share as an efficiency pressure with recoverable-flow caveats. Do not treat food production dependence as food lost or all apparent loss as destroyed water.',
    },
    referenceBasis: {
      type: isOverdraft ? 'source_declared_global_groundwater_depletion_range' : 'source_declared_global_sector_pressure_share', start: startYear, end: evidenceYear,
      purpose: `Assess ${label} from its directly reported physical or sector-pressure quantity while withholding terminal consequences and denominators the source does not measure.`,
    },
    history: {
      mode: 'published_hindcast', recordStartYear: startYear, recordEndYear: evidenceYear, completeCalendarPeriods: true,
      coverageExceptionReason: 'The source describes a period, acceleration start or current aggregate rather than a complete annual panel. The elapsed period is context and is not used as consequence duration.',
      metric: isOverdraft ? 'Global aggregated groundwater storage depletion rate and share of withdrawals.' : isAgricultural ? 'Agricultural share of groundwater abstraction and irrigated-land dependence.' : isMunicipal ? 'Domestic share of groundwater abstraction and urban service dependence.' : 'Irrigation conveyance and application loss share with recoverable-flow caveats.',
      earlyBaseline: isOverdraft ? 'The compatible global depletion assessment begins in 2000.' : `The source uses ${startYear} as the beginning of the broader pressure context; it is not a zero-harm baseline.`,
      recentState: directFact,
      currentState: isOverdraft ? 'The source establishes physical depletion at global aggregate scale but does not identify unique people in shortage, ecosystem-condition loss or recovery time.' : `The source establishes the scale of ${label} as pressure or dependence. It does not establish a matching terminal human or ecosystem consequence.`,
      fullRecordTrend: 'The stated start year and assessment year do not form an annual observation series and are not converted into persistence.',
      observedImpact: isOverdraft ? 'Groundwater storage is being depleted globally in aggregate. Human water dependence remains exposure and cannot be counted as realized shortage.' : 'The directly supported observation is pressure on the water system. Downstream shortage, crop loss, land subsidence, salinity and ecosystem decline remain separate outcomes.',
      attribution: isOverdraft ? 'The aggregate depletion range reflects withdrawals exceeding replenishment across heterogeneous aquifers; it cannot be allocated to agricultural, municipal or industrial sectors from their abstraction shares.' : `The sector share is attributable to ${label}, but the source does not assign a share of global aquifer depletion or terminal harm to it.`,
      limitations: 'The evidence supplies no compatible unique harmed-person count, affected ecosystem-distribution share or consequence-recovery distribution. Global service dependence is exposure.',
      evidenceReferences: [sourceId],
    },
    outlook: {
      horizon: policy.horizon, scenario: policy.scenario, direction: 'mixed', confidence: 'C',
      basis: 'The admitted assessment is not a compatible 2027–2036 SSP2-4.5 terminal-consequence projection. No numerical outlook increment is added.',
      evidenceReferences: [sourceId],
    },
    ...(isOverdraft ? {
      human: {
        severity: { lower: 0, central: 1, upper: 2, sourceAnchored: false, basis: 'Physical aquifer depletion creates a material risk state, but the source measures no current shortage, illness, displacement or attributable material loss. A limited central consequence is retained.' },
        reach: { lower: 0, central: 1, upper: 2, sourceAnchored: false, basis: 'Half of domestic withdrawals being groundwater-dependent is exposure, not people harmed. No compatible unique-person consequence count is available.' },
        persistence: { lower: 0, central: 1, upper: 2, sourceAnchored: false, basis: 'The 2000–2022 assessment period is not human consequence duration. Acute central persistence is provisional pending shortage or recovery evidence.' },
      },
    } : {}),
    ecosystem: isOverdraft ? {
      severity: { lower: 0, central: 1, upper: 2, sourceAnchored: false, basis: 'Storage depletion is a physical state rather than a measured ecosystem-condition percentage. A detectable-pressure central level is retained.' },
      reach: { lower: 0, central: 1, upper: 2, sourceAnchored: false, basis: 'Global aggregation does not mean all groundwater-dependent ecosystems are damaged. No affected-distribution denominator is provided.' },
      persistence: { lower: 0, central: 2, upper: 3, sourceAnchored: false, basis: 'Aquifer depletion can take multiple years to reverse, but the source supplies no ecosystem recovery distribution. Assessment duration is excluded.' },
    } : {
      severity: { lower: 0, central: 1, upper: 2, sourceAnchored: false, basis: `The reported ${label} quantity establishes pressure, not measured ecosystem-condition loss. A detectable-pressure central level is retained.` },
      reach: { lower: 0, central: 1, upper: 2, sourceAnchored: false, basis: 'Sector share, dependent land, urban population, country coverage and global scope are not affected-ecosystem denominators.' },
      persistence: { lower: 0, central: 1, upper: 2, sourceAnchored: false, basis: 'A start year or annually recurring withdrawal does not measure ecosystem recovery. Acute central persistence is provisional.' },
    },
    measurementSemantics: {
      severity: 'Use realized human consequences and measured ecosystem-condition loss. Depletion volume, withdrawal share, efficiency loss and dependence are physical state or pressure.',
      reach: 'Use unique harmed people and affected ecosystem distribution. Do not use urban population supplied, irrigated land, food-production share, sector share, countries or global coverage.',
      persistence: 'Use consequence or recovery duration. Do not use the assessment period, demand-growth interval, annual recurrence or acceleration start year.',
      nonDoubleCounting: 'Do not add groundwater depletion, recharge failure, land subsidence, salinity, irrigation, crop-loss, water-shortage or drinking-water scores. Sector shares do not receive portions of the aggregate depletion volume.',
    },
    causalAllocation: {
      role: isOverdraft ? 'hazard_or_state' : 'aggregate_pressure',
      counterfactual: `Compare terminal consequences under observed ${label} with otherwise comparable water systems without the excess pressure, retaining recharge, climate, geology, demand, return flow and management as modifiers.`,
      aggregationDenominator: 'Unique people with attributable terminal consequences and groundwater-dependent ecosystems with measured condition loss.',
      overlapExclusions: ['Do not treat groundwater dependence as observed shortage.', 'Do not allocate aggregate depletion by sector abstraction share.', 'Do not add recharge, subsidence, salinity, crop-loss, irrigation or water-shortage scores.'],
      limitations: 'The source measures global pressure and dependence more directly than terminal human or ecosystem consequences.',
    },
    reviewEvidence: [{ id: sourceId, url: groundwaterIrrigationReference.source.groundwater_report_url, checkedOn: '2026-09-26', finding: `${directFact} UNESCO/FAO explicitly warns that dependence is not shortage, sector share is not sector-attributed depletion, and some irrigation return flow is recoverable.` }],
    finding: isOverdraft
      ? 'Revised D 7.4 to B 3.6 with an A–C range. The global depletion rate establishes physical state, while domestic dependence is exposure, global scope is not affected reach and the 22-year assessment period is not consequence persistence.'
      : `Revised D 7.4 to B 3.3 and changed to ecosystem-only pressure. The former score treated dependence, global coverage and elapsed assessment time as terminal harm for ${label}. Those quantities are now kept outside severity, reach and persistence.`,
  };
}

