      reach: { lower: 0, central: 1, upper: 2, sourceAnchored: false, basis: 'Global production scope does not measure the affected share of any ecosystem distribution.' },
      persistence: { lower: 0, central: 2, upper: 3, sourceAnchored: false, basis: 'Multi-year emissions-intensity pressure supports a recurring central level, but the comparison interval is not ecological recovery time.' },
