function gulfStreamTransportOverride() {
  const s = floridaCurrentReference.source_summary;
  const latest = s.annual_means.at(-1);
  const differencePct = Number((((latest.mean_transport_sverdrups / s.long_term_reference_transport_sverdrups) - 1) * 100).toFixed(1));
  return observedClimateStateOverride({
    label: 'Gulf Stream Transport and Position',
    sourceId: floridaCurrentReference.source.id,
    sourceUrl: floridaCurrentReference.source.documentation_url,
    latestYear: latest.observation_year,
    currentStart: latest.observation_year,
    currentEnd: latest.observation_year,
    recordStart: s.first_complete_year,
    recordEnd: latest.observation_year,
    metric: 'Annual mean Florida Current transport at 27 degrees north in sverdrups.',
    referenceSummary: 'Compare annual Florida Current transport at 27 degrees north with the NOAA 32-sverdrup long-term reference for the same section and product.',
    recentState: 'The 2025 annual mean was ' + latest.mean_transport_sverdrups + ' sverdrups, ' + Math.abs(differencePct) + '% ' + (differencePct < 0 ? 'below' : 'above') + ' the 32-sverdrup reference.',
    currentState: 'The observed section is below its reference, but it is one bounded upper-ocean section rather than the entire Gulf Stream or AMOC.',
    physicalBoundary: floridaCurrentReference.uncertainty + ' ' + floridaCurrentReference.caveats[0],
    reachCentral: 1,
    persistenceCentral: 2,
    evidenceFinding: 'NOAA supplies 23 complete annual observations through 2025. The latest Florida Current mean is ' + latest.mean_transport_sverdrups + ' sverdrups versus the 32-sverdrup reference; this section cannot establish whole-current slowdown or terminal consequences.',
    finding: 'Revised D 7.0 to B 4.0, with an A 1.0–D 7.8 range. The 2025 Florida Current observation now anchors a bounded physical state, while one section, its 23-year record and downstream AMOC narratives no longer become harm severity, reach or persistence.',
  });
}

function boundedEcosystemEvidenceOverride({
  latestYear, currentStart, currentEnd, recordStart, recordEnd, coverageNote, normalization,
  referenceType, referencePurpose, metric, earlyBaseline, recentState, currentState,
  fullRecordTrend, observedImpact, attribution, limitations, sourceIds, outlookBasis,
  ecosystem, measurementSemantics, causalAllocation, reviewEvidence, finding,
}) {
  return ecosystemOnlyDetailedOverride({
    latestCompatibleEvidenceYear: latestYear,
    currentWindow: {
      start: currentStart, end: currentEnd, coverageStatus: 'partial', summaryMethod: 'period_prevalence',
      coverageNote, isLatestAvailable: true, recencyCheckedOn: '2026-09-26',
      recencyRationale: 'The cited assessment is the newest compatible source in the local registry.',
      normalization,
    },
    referenceBasis: { type: referenceType, start: recordStart, end: recordEnd, purpose: referencePurpose },
    history: {
      mode: 'direct_record', recordStartYear: recordStart, recordEndYear: Math.min(recordEnd, 2025), completeCalendarPeriods: true,
      coverageExceptionReason: coverageNote, metric, earlyBaseline, recentState, currentState,
      fullRecordTrend, observedImpact, attribution, limitations, evidenceReferences: sourceIds,
    },
    outlook: {
      horizon: policy.horizon, scenario: policy.scenario, direction: 'mixed', confidence: 'D',
      basis: outlookBasis, evidenceReferences: sourceIds,
    },
    ecosystem, measurementSemantics, causalAllocation, reviewEvidence, finding,
  });
}

