assert.equal(Object.keys(deferredP3ReviewConfigs).length, 46);

function deferredP3AxisSet(spec, label, kind) {
  const normalized = Array.isArray(spec) ? { bounds: spec } : spec;
  const [lower, central, upper] = normalized.bounds;
  const names = ['severity', 'reach', 'persistence'];
  const defaultBasis = {
    severity: `The source establishes ${kind} for ${label}; terminal-consequence magnitude is used only where the source directly reports it.`,
    reach: 'The assessment uses a compatible harmed-person count or affected ecosystem share where available; monitoring coverage, physical extent and exposure remain separate.',
    persistence: 'The assessment uses consequence or recovery duration where available; source age, observation span and recurrence of the upstream state do not set persistence.',
  };
  return Object.fromEntries(names.map((name, index) => [name, {
    lower: lower[index], central: central[index], upper: upper[index],
    sourceAnchored: normalized.anchored?.[index] ?? false,
    basis: normalized.basis?.[index] ?? defaultBasis[name],
  }]));
}

function deferredP3DetailedOverride(nodeId) {
  const config = deferredP3ReviewConfigs[nodeId];
  const node = nodesById.get(nodeId);
  const record = registry.records[nodeId];
  const prior = firstPassById.get(nodeId)?.candidate;
  assert(config && node && record && prior, `Missing deferred P3 review input for ${nodeId}`);
  const history = prior.history;
  const evidenceYear = Number(String(record.evidenceAudit.sourceAsOf).match(/(?:19|20)\d{2}/)?.[0] ?? prior.currentWindow.end);
  const sourceFinding = `The registered source directly supplies ${record.evidenceAudit.metric.toLowerCase()} within its declared geography and period. ${config.boundary}`;
  const sources = record.evidenceReferences.map(reference => ({
    id: reference.id, url: reference.url, finding: sourceFinding,
  }));
  const humanSpec = config.human ?? (config.domains.includes('human') ? config.same : null);
  const ecosystemSpec = config.ecosystem ?? (config.domains.includes('ecosystem') ? config.same : null);
  return boundedCatalogueEvidenceOverride({
    label: node.name.toLowerCase(), domains: config.domains, confidence: config.confidence,
    recordStart: history.recordStartYear ?? prior.currentWindow.start,
    recordEnd: history.recordEndYear ?? prior.currentWindow.end,
    currentStart: prior.currentWindow.start, currentEnd: prior.currentWindow.end,
    latestEvidenceYear: evidenceYear,
    coverageStatus: prior.currentWindow.coverageStatus,
    summaryMethod: prior.currentWindow.summaryMethod,
    coverageNote: `The evidence is source-specific for ${record.evidenceAudit.metric.toLowerCase()}, while its terminal-consequence coverage is limited to the boundary stated in this review.`,
    coverageExceptionReason: history.coverageExceptionReason ?? 'The admitted record does not provide a complete global annual terminal-consequence panel; missing geographies and years are not imputed.',
    normalization: `Use ${record.evidenceAudit.metric.toLowerCase()} once within the source boundary. Do not convert monitoring scope, physical magnitude, activity, exposure or record length into harm.`,
    referenceBasis: prior.referenceBasis,
    metric: record.evidenceAudit.metric,
    earlyBaseline: history.earlyBaseline,
    recentState: history.recentState,
    currentState: config.boundary,
    fullRecordTrend: 'The source-native record is retained for direction and context. Its duration is not multiplied into current harm and does not substitute for consequence or recovery time.',
    observedImpact: config.boundary,
    attribution: 'Only consequences attributable within this node boundary enter its axes. Connected causes, exposures and downstream outcomes retain their own ratings.',
    limitations: `The source-specific review preserves the source geography, period, denominator and causal limits. ${config.boundary}`,
    human: humanSpec ? deferredP3AxisSet(humanSpec, node.name, config.kind) : null,
    ecosystem: ecosystemSpec ? deferredP3AxisSet(ecosystemSpec, node.name, config.kind) : null,
    sources,
    evidenceReferences: record.evidenceReferences.map(reference => reference.id),
    causalRole: config.role,
    counterfactual: `Compare terminal consequences under the observed ${node.name} state with otherwise comparable conditions at the source-defined reference, retaining other drivers, exposures and responses.`,
    aggregationDenominator: 'Unique people with attributable consequences and/or the affected share of a compatible ecosystem distribution, according to the applicable domain.',
    overlapExclusions: ['Do not use source or monitoring coverage as harmed reach.', 'Do not use record length as consequence duration.', 'Do not add connected driver, exposure or downstream outcome scores.'],
    finding: `Completed the deferred source-specific review. ${config.boundary}`,
  });
}

