function emissionSourceEndpointOverride(endpointRow) {
  const node = nodesById.get(endpointRow.nodeId);
  const record = registry.records[endpointRow.nodeId];
  const prior = firstPassById.get(endpointRow.nodeId);
  assert(node && record && prior, `${endpointRow.nodeId}: endpoint review inputs missing`);
  const facts = evidenceFacts(record);
  const human = {
    severity: peopleSeverity(node, record, facts),
    reach: peopleReach(node, facts),
    persistence: persistence(node, record, facts, 'human'),
  };
  const ecosystem = {
    severity: natureSeverity(node, record, facts),
    reach: natureExtent(node, facts),
    persistence: persistence(node, record, facts, 'ecosystem'),
  };
  const sensitivity = endpointRow.humanEndpointStage.sensitivity;
  const centralCase = sensitivity.patternCases.find(item => item.patternScale === 1);
  assert(centralCase, `${endpointRow.nodeId}: central heat-endpoint sensitivity missing`);
  const latest = endpointRow.sourceHistoryStage.latestMeasurement;
  const annualSeries = endpointRow.physicalStage.annualSeries;
  const sourceEvidence = record.evidenceReferences.map(reference => reference.id);
  const familyValue = endpointRow.retainedCandidate.value;
  const familyGrade = endpointRow.retainedCandidate.grade;
  const sourceGas = sensitivity.sourceGas;
  const physicalResponseBasis = sensitivity.physicalResponseBasis;
  const patternPipeline = endpointRow.humanEndpointStage
    .regionalPatternDataGap
    .candidateIndependentEuropeanEndpointBridge
    .longRecordPreparation;
  const matchedSourceRemovalEndpoint = patternPipeline.matchedSourceRemovalHumanEndpoint ?? null;
  const regionalPatternPromotion = patternPipeline.regionalPatternPromotion ?? null;
  const exactWeekPatternAnalysis = patternPipeline.exactWeekIndependentPatternAnalysis ?? null;
  const monthlyPatternAnalysis = patternPipeline.monthlyIndependentPatternAnalysis ?? null;
  const era5PatternAnalysis = patternPipeline.patternAnalysis ?? null;
  const era5Execution = patternPipeline.execution;
  const regionalPatternStatus = matchedSourceRemovalEndpoint?.status
    ?? regionalPatternPromotion?.status
    ?? exactWeekPatternAnalysis?.comparison?.status
    ?? monthlyPatternAnalysis?.comparison?.status
    ?? era5PatternAnalysis?.status
    ?? era5Execution.status;
  const regionalPatternPromotionDecision = regionalPatternPromotion
    ?.admissionDecision
    ?.patternInputAdmittedToMatchedEndpoint ?? null;
  const regionalPatternResearchStatus = matchedSourceRemovalEndpoint
    ? 'matched_source_removal_human_endpoint_complete_axis_mapping_and_ecosystem_pending'
    : regionalPatternPromotion
    ? regionalPatternPromotionDecision
      ? 'regional_pattern_input_promoted_matched_endpoint_and_ecosystem_endpoint_pending'
      : 'regional_pattern_rejected_family_candidate_retained'
    : exactWeekPatternAnalysis
      ? 'exact_week_independent_pattern_analysis_complete_promotion_pending'
      : monthlyPatternAnalysis
        ? 'monthly_independent_pattern_analysis_complete_exact_week_and_promotion_pending'
        : era5PatternAnalysis
          ? 'era5_long_record_pattern_analysis_complete_independent_promotion_pending'
          : era5Execution.status === 'complete_long_record_retrieval'
            ? 'era5_long_record_retrieval_complete_pattern_analysis_pending'
            : 'era5_long_record_retrieval_in_progress';
  const regionalPatternProgress = matchedSourceRemovalEndpoint
    ? 'The independently admitted regional pattern has been propagated through all compatible source histories, 971 regions, 2000–2022 observations, three separate physical-response cases and all 100 fixed epidemiological bootstrap fits. The matched human endpoint is complete; reviewed axis mapping and the ecosystem endpoint remain pending.'
    : regionalPatternPromotion
    ? regionalPatternPromotionDecision
      ? 'The frozen monthly and exact-week comparison admitted the ERA5 regional pattern only as an input to the matched mortality endpoint. The complete endpoint, all 100 bootstrap fits and the ecosystem endpoint remain pending.'
      : 'The frozen monthly and exact-week comparison rejected the ERA5 regional pattern for the source-removal endpoint, so the family candidate is retained while a compatible regional pattern is sought.'
    : exactWeekPatternAnalysis
      ? 'The monthly and exact-week independent pattern analyses are complete; the frozen promotion decision and matched endpoint remain pending.'
      : monthlyPatternAnalysis
        ? 'The 22-model, 17-institution monthly independent pattern analysis is complete; ERA5 completion, the exact-week challenge and the frozen promotion decision remain pending.'
        : era5PatternAnalysis
          ? 'The ERA5 long-record regional pattern has been analyzed; the independent comparison, promotion decision and matched endpoint remain pending.'
          : era5Execution.status === 'complete_long_record_retrieval'
            ? 'The ERA5 long record is complete; regional-pattern analysis and independent comparison remain pending.'
            : `ERA5 long-record retrieval is in progress (${era5Execution.completedYearCount} of 73 years complete); partial coverage cannot enter a rating.`;
  const physicalHistoryLabel = sourceGas === 'CH4'
    ? 'path-dependent rice-methane GWP* response'
    : 'partial cumulative CO2 response';
  const temperatureText = `${sensitivity.cumulativeGmstScreenC2022.toFixed(6)} °C`;
  const deathText = centralCase.sourceAttributableHeatDeaths.toFixed(
    centralCase.sourceAttributableHeatDeaths < 10 ? 2 : 1,
  );
  const append = (axis, text) => ({
    ...axis,
    sourceAnchored: false,
    basis: `${text} The level-${axis.central} central value remains family-calibrated; this sensitivity is recorded as a challenge to the rating rather than treated as a validated global estimate.`,
  });
  human.severity = append(human.severity, `The nonlinear 103-region 2022 sensitivity estimates ${deathText} source-attributable heat deaths under a uniform ${temperatureText} local shift. The regional shift and full endpoint are not yet validated, so the modeled deaths do not set severity.`);
  human.reach = append(human.reach, `The open endpoint covers 103 Italian regions and 61.1 million residents. That sample is neither a global harmed-person denominator nor a count of unique people harmed by this source.`);
  human.persistence = append(human.persistence, 'A validated attributable death would be permanent, but the current run does not establish a complete source-attributable burden or the duration of other human consequences.');
  ecosystem.severity = append(ecosystem.severity, 'No paired factual-versus-source-removal ecosystem-condition endpoint is available. Emissions mass, cumulative warming and modeled heat deaths do not measure movement toward ecosystem collapse.');
  ecosystem.reach = append(ecosystem.reach, 'No compatible share of an ecosystem distribution has source-attributable condition loss. Global atmospheric mixing and model coverage are excluded from reach.');
  ecosystem.persistence = append(ecosystem.persistence, 'No source-removal ecosystem recovery distribution is available. Carbon lifetime and the emissions-record length are physical context rather than ecological recovery time.');
  const aggregateNodeIds = unresolvedEmissionSources.get(endpointRow.nodeId);
  assert(aggregateNodeIds, `${endpointRow.nodeId}: emission-source mapping missing`);
  return {
    domains: prior.candidate.applicableDomains,
    confidence: 'D',
    latestCompatibleEvidenceYear: Number(latest.year),
    currentWindow: {
      start: 2022,
      end: 2022,
      coverageStatus: 'partial',
      summaryMethod: 'event_distribution',
      coverageNote: 'The only source-specific terminal-consequence calculation is a 2022 heat-mortality sensitivity for the public 103-region Italian sample. The emissions history extends farther, but a physical source record is not itself current harm.',
      isLatestAvailable: true,
      recencyCheckedOn: '2026-09-25',
      recencyRationale: `This is the newest reproducible source-specific human endpoint currently available in the repository. ${regionalPatternProgress}`,
      normalization: `Keep the ${physicalHistoryLabel}, its temperature response and the nonlinear heat endpoint in their native units. Do not convert annual emissions, global mixing or physical warming directly into TULIP axes.`,
    },
    referenceBasis: {
      type: 'source_removal_counterfactual_sensitivity',
      start: annualSeries.firstYear,
      end: 2022,
      purpose: `Compare the observed 2022 heat endpoint with the same public regional model after removing the ${physicalHistoryLabel} attributed to this node over the available ${annualSeries.firstYear}–2022 response record. This tests responsiveness but is not yet an admitted global attribution.`,
    },
    history: {
      mode: 'reconstructed_record',
      recordStartYear: annualSeries.firstYear,
      recordEndYear: annualSeries.lastYear,
      completeCalendarPeriods: true,
      coverageExceptionReason: endpointRow.physicalStage.boundary,
      metric: `${latest.unit} source flow, ${physicalHistoryLabel}, global-mean temperature response and a nonlinear 2022 regional heat-mortality sensitivity.`,
      earlyBaseline: `The physical response series begins in ${annualSeries.firstYear}. Earlier source emissions are not imputed, so the contribution is a partial physical screen rather than a complete historical attribution.`,
      recentState: `The latest source measurement is ${latest.value.toLocaleString('en-US')} ${latest.unit} in ${latest.year}. It is an emissions input and does not set harm severity or reach.`,
      currentState: `The partial history produces a 2022 global-mean warming screen of ${temperatureText}. Under the unvalidated 1× regional-pattern sensitivity, the public model estimates ${deathText} attributable heat deaths across its 103-region sample.`,
      fullRecordTrend: `The physical response series contains ${annualSeries.records} annual records from ${annualSeries.firstYear} through ${annualSeries.lastYear}. The record length and cumulative temperature response remain outside consequence persistence.`,
      observedImpact: `A node-specific nonlinear human sensitivity has run. ${regionalPatternProgress} No compatible source-specific ecosystem endpoint exists.`,
      attribution: `The counterfactual removes this recorded source response without assuming replacement emissions. It does not copy the ${aggregateNodeIds.join(' or ')} score, multiply aggregate harm by an annual share or add downstream node scores.`,
      limitations: `${endpointRow.humanEndpointStage.limitation} ${endpointRow.ecosystemEndpointStage.limitation}`,
      evidenceReferences: sourceEvidence,
    },
    human,
    ecosystem,
    measurementSemantics: {
      severity: 'Validated terminal loss under the matched source-removal counterfactual. Tonnes of CO2 and global-mean warming are intermediate physical quantities.',
      reach: 'Unique people harmed and the compatible share of ecosystem distributions with condition loss. Sample population and atmospheric coverage do not substitute for those denominators.',
      persistence: 'Duration or irreversibility of attributed terminal consequences. Carbon lifetime and observation length are not consequence duration.',
      nonDoubleCounting: 'The sensitivity recomputes the endpoint after source removal. It does not add Carbon Emissions, global warming, heatwave or heat-mortality node ratings.',
    },
    causalAllocation: {
      role: 'emission_source',
      aggregateNodeIds,
      attributionStatus: 'unresolved',
      researchStatus: regionalPatternResearchStatus,
      researchRecord: 'artifacts/tulip-calibration-2026-09-22/internal-emission-source-endpoint-pilot.json',
      sourceEvidenceRecord: 'artifacts/tulip-calibration-2026-09-22/internal-emission-source-heat-endpoint-sensitivity.json',
      inheritsAggregateScore: false,
      scoreResponseStatus: 'provisional_family_candidate_not_yet_calibrated_to_source_specific_endpoint',
      counterfactual: `Compare current terminal harm with the same climate and socioeconomic system after removing the emissions history attributable to ${endpointRow.nodeId}, without assuming another source replaces it.`,
      aggregationDenominator: 'A compatible source-removal climate response followed by matched, non-overlapping terminal human and ecosystem endpoints over declared populations and ecosystem distributions.',
      endpointSensitivity: {
        year: 2022,
        sourceGas,
        physicalResponseBasis,
        publicSampleRegions: sensitivity.publicSampleRegions,
        cumulativeGmstScreenC2022: sensitivity.cumulativeGmstScreenC2022,
        centralPatternScale: centralCase.patternScale,
        centralSourceAttributableHeatDeaths: centralCase.sourceAttributableHeatDeaths,
        admittedToAxes: false,
      },
      regionalPatternEvidence: {
        status: regionalPatternStatus,
        nextGate: endpointRow.nextAction,
        monthlyComparisonStatus: monthlyPatternAnalysis?.comparison?.status ?? null,
        exactWeekComparisonStatus: exactWeekPatternAnalysis?.comparison?.status ?? null,
        promotionDecision: regionalPatternPromotionDecision,
        matchedHumanEndpointCompleted: matchedSourceRemovalEndpoint?.humanEndpointCompleted ?? false,
      },
      overlapExclusions: [
        `Do not copy or multiply the ${aggregateNodeIds.join(' or ')} score.`,
        'Do not add downstream warming, hazard and endpoint-node scores to the source candidate.',
        'Do not treat annual emissions tonnage or cumulative warming as a direct severity, reach or persistence value.',
      ],
      limitations: `The current numerical rating is deliberately retained as a confidence-D family candidate. ${regionalPatternProgress} The rating cannot change until a compatible regional pattern has been propagated through the full human endpoint and a matched ecosystem counterfactual is calibrated.`,
    },
    reviewEvidence: [
      ...record.evidenceReferences.map(reference => ({ ...reference, checkedOn: 'repository_evidence_registry_2026-09-25' })),
      {
        id: 'tulip_emission_source_heat_endpoint_sensitivity_2026_09_25_v6',
        url: 'https://github.com/BallesterJoan/europe_summer_2022_heat',
        checkedOn: '2026-09-25',
        finding: `The source-removal run produces ${deathText} heat deaths in the central sensitivity from a ${temperatureText} partial 2022 warming contribution. The result uses a uniform regional shift and the public 103-region sample, so it is retained as a challenge case rather than an axis value.`,
      },
    ],
    finding: `${familyGrade} ${familyValue.toFixed(1)} is retained at confidence D. This detailed review adds the node-specific emissions history, ${physicalHistoryLabel} and nonlinear heat-endpoint sensitivity. ${regionalPatternProgress} The rating is still family-calibrated and not yet responsive to the source-specific endpoint.`,
  };
}

for (const endpointRow of emissionSourceEndpointPilot.rows.filter(row => row.humanEndpointStage?.sensitivity)) {
  assert.equal(detailedOverrides[endpointRow.nodeId], undefined, `${endpointRow.nodeId}: duplicate detailed override`);
  detailedOverrides[endpointRow.nodeId] = emissionSourceEndpointOverride(endpointRow);
}

function emissionSourceInventoryOverride(endpointRow) {
  const node = nodesById.get(endpointRow.nodeId);
  const record = registry.records[endpointRow.nodeId];
  const prior = firstPassById.get(endpointRow.nodeId);
  assert(node && record && prior, `${endpointRow.nodeId}: inventory review inputs missing`);
  const facts = evidenceFacts(record);
  const latest = endpointRow.sourceHistoryStage.latestMeasurement;
  const registryYear = Number(record.evidenceAudit.sourceAsOf.match(/(?:19|20)\d{2}/)?.[0] ?? 0);
  const measurementYear = Number(latest?.year);
  const latestYear = Number.isInteger(measurementYear) && measurementYear >= 1900
    ? measurementYear
    : Number(latest?.context?.year) || registryYear;
  const historyEndYear = Math.min(latestYear, 2025);
  const annualSeries = endpointRow.physicalStage.annualSeries ?? null;
  const boundaryAudit = endpointRow.sourceHistoryStage.boundaryAudit ?? null;
  const latestText = Number.isFinite(latest?.value)
    ? `${latest.value.toLocaleString('en-US')} ${latest.unit} in ${latest.year}`
    : 'no compatible node-specific global mass flow';
  const physicalOutput = endpointRow.physicalStage.output;
  const physicalText = physicalOutput == null
    ? 'No source-removal climate response has passed the physical stage.'
    : `The reproduced physical response is ${typeof physicalOutput === 'number' ? physicalOutput : JSON.stringify(physicalOutput)}; it remains an intermediate quantity rather than harm.`;
  const append = (axis, text) => ({
    ...axis,
    sourceAnchored: false,
    basis: `${text} The level-${axis.central} central value remains a confidence-D family calibration because no source-specific terminal endpoint is available.`,
  });
  const human = {
    severity: append(peopleSeverity(node, record, facts), 'The inventory does not measure source-attributable death, illness, displacement, material loss or essential-service interruption.'),
    reach: append(peopleReach(node, facts), 'The inventory geography and globally mixed atmosphere do not count unique people harmed.'),
    persistence: append(persistence(node, record, facts, 'human'), 'The emissions series and gas lifetime do not measure how long an attributed human consequence lasts.'),
  };
  const ecosystem = {
    severity: append(natureSeverity(node, record, facts), 'The inventory does not measure source-attributable ecosystem condition loss against a collapse or functional-loss reference.'),
    reach: append(natureExtent(node, facts), 'No compatible share of an ecosystem distribution with attributed condition loss is available.'),
    persistence: append(persistence(node, record, facts, 'ecosystem'), 'The physical record does not measure ecosystem recovery after removing this source.'),
  };
  const aggregateNodeIds = unresolvedEmissionSources.get(endpointRow.nodeId);
  assert(aggregateNodeIds, `${endpointRow.nodeId}: emission-source mapping missing`);
  return {
    domains: prior.candidate.applicableDomains,
    confidence: 'D',
    latestCompatibleEvidenceYear: latestYear,
    currentWindow: {
      start: annualSeries?.firstYear ?? latestYear,
      end: annualSeries?.lastYear ?? latestYear,
      coverageStatus: 'partial',
      summaryMethod: annualSeries ? 'annualized_flow' : 'end_state_stock',
      coverageNote: `The source stage is ${endpointRow.sourceHistoryStage.status}. ${endpointRow.physicalStage.boundary}${boundaryAudit ? ` Boundary audit: ${boundaryAudit.finding}` : ''}`,
      isLatestAvailable: true,
      recencyCheckedOn: '2026-09-25',
      recencyRationale: 'The review records the newest compatible source inventory currently bound to this node and the exact next missing stage. A physical input is not promoted into harm.',
      normalization: 'Keep gas, mass-flow, boundary and time-series units source-native. Do not use annual tonnes, inventory coverage, global mixing or record length as harm severity, reach or persistence.',
    },
    referenceBasis: {
      type: 'source_removal_counterfactual_pending',
      start: annualSeries?.firstYear ?? historyEndYear,
      end: annualSeries?.lastYear ?? historyEndYear,
      purpose: `Prepare a non-overlapping ${endpointRow.nodeId} emissions history for removal from the climate system before any terminal human or ecosystem endpoint is calibrated.`,
    },
    history: {
      mode: annualSeries ? 'reconstructed_record' : 'direct_record',
      recordStartYear: annualSeries?.firstYear ?? historyEndYear,
      recordEndYear: annualSeries?.lastYear ?? historyEndYear,
      completeCalendarPeriods: true,
      coverageExceptionReason: endpointRow.physicalStage.boundary,
      metric: latest?.unit ? `${latest.unit} source flow` : 'Source-specific mass flow still required',
      earlyBaseline: annualSeries
        ? `The admitted response series begins in ${annualSeries.firstYear}; earlier source contributions are not imputed.`
        : 'A compatible historical source series has not yet been admitted, so no earlier baseline is inferred from aggregate industry or sector totals.',
      recentState: `The latest inventory state is ${latestText}. Its quality is recorded as ${latest?.quality ?? 'not available'}.`,
      currentState: `${physicalText} The human endpoint is ${endpointRow.humanEndpointStage.status}, and the ecosystem endpoint is ${endpointRow.ecosystemEndpointStage.status}.`,
      fullRecordTrend: annualSeries
        ? `The response series contains ${annualSeries.records} records from ${annualSeries.firstYear} through ${annualSeries.lastYear}. Its duration does not set consequence persistence.`
        : 'No compatible annual node-specific series is available, so a trend is not synthesized from aggregate context.',
      observedImpact: `No matched source-specific terminal human or ecosystem consequence is available for this node.${boundaryAudit ? ` The boundary audit admits only this use: ${boundaryAudit.admittedUse}` : ''}`,
      attribution: `The required counterfactual removes only ${endpointRow.nodeId}, preserves other sources and does not assume replacement emissions.`,
      limitations: `${endpointRow.humanEndpointStage.limitation} ${endpointRow.ecosystemEndpointStage.limitation}${boundaryAudit ? ` ${boundaryAudit.prohibitedUse}` : ''}`,
      evidenceReferences: record.evidenceReferences.map(reference => reference.id),
    },
    human,
    ecosystem,
    measurementSemantics: {
      severity: 'Matched terminal human or ecosystem loss after source removal. Inventory magnitude and physical climate response are inputs only.',
      reach: 'Unique people harmed and affected ecosystem distribution, excluding inventory coverage and global atmospheric mixing.',
      persistence: 'Duration or recovery of attributed terminal harm, excluding gas lifetime and record length.',
      nonDoubleCounting: 'Aggregate Carbon Emissions or Methane ratings and downstream climate, hazard and endpoint scores are not copied or added.',
    },
    causalAllocation: {
      role: 'emission_source',
      aggregateNodeIds,
      attributionStatus: 'unresolved',
      researchStatus: `${endpointRow.sourceHistoryStage.status}__${endpointRow.physicalStage.status}__terminal_endpoints_pending`,
      researchRecord: 'artifacts/tulip-calibration-2026-09-22/internal-emission-source-endpoint-pilot.json',
      inheritsAggregateScore: false,
      scoreResponseStatus: 'provisional_family_candidate_no_source_specific_endpoint',
      sourceHistoryFeasibility: boundaryAudit ? {
        version: boundaryAudit.version,
        status: boundaryAudit.status,
        finding: boundaryAudit.finding,
        admittedUse: boundaryAudit.admittedUse,
        prohibitedUse: boundaryAudit.prohibitedUse,
        nextRequiredData: boundaryAudit.nextRequiredData,
        ratingEffect: boundaryAudit.ratingEffect,
      } : null,
      counterfactual: `Compare current terminal harm with the same climate and socioeconomic system after removing the emissions history attributable to ${endpointRow.nodeId}, without assuming another source replaces it.`,
      aggregationDenominator: 'A non-overlapping annual source history, source-removal climate response and matched terminal human and ecosystem endpoints.',
      overlapExclusions: [
        `Do not copy or multiply the ${aggregateNodeIds.join(' or ')} score.`,
        'Do not add downstream warming, hazard and endpoint-node scores to the source candidate.',
        'Do not treat annual emissions tonnage, inventory coverage or physical response as direct harm axes.',
      ],
      limitations: 'The numerical candidate remains family-calibrated at confidence D. The inventory and physical-stage evidence now identify the exact missing causal step rather than implying that the provisional score is source-specific.',
    },
    reviewEvidence: record.evidenceReferences.map(reference => ({ ...reference, checkedOn: 'repository_evidence_registry_2026-09-25' })),
    finding: `${endpointRow.retainedCandidate.grade} ${endpointRow.retainedCandidate.value.toFixed(1)} is retained at confidence D. The detailed review records ${latestText}, the physical-stage status and the absence of matched human and ecosystem endpoints; the rating is not presented as a source-attributable calculation.${boundaryAudit ? ` The checksum-backed boundary audit rejects the available aggregate or proxy history for node-specific attribution and requires: ${boundaryAudit.nextRequiredData}` : ''}`,
  };
}

for (const endpointRow of emissionSourceEndpointPilot.rows.filter(row => !row.humanEndpointStage?.sensitivity)) {
  if (detailedOverrides[endpointRow.nodeId]) continue;
  detailedOverrides[endpointRow.nodeId] = emissionSourceInventoryOverride(endpointRow);
}

function blindReview(node, record) {
  const facts = evidenceFacts(record);
  const override = detailedOverrides[node.id];
  const authoredDomains = firstPassById.get(node.id)?.candidate?.applicableDomains;
  const directDomains = directDomainOverrides.get(node.id);
  const domains = override?.domains ?? directDomains ?? authoredDomains ?? applicability(node, record);
  const domainScopeRule = override?.domains
    ? 'detailed_evidence_review_override'
    : directDomains
      ? 'explicit_direct_domain_override'
      : authoredDomains
        ? 'authored_node_boundary_preserved'
        : 'text_inference_fallback';
  const confidence = override?.confidence ?? (unresolvedEmissionSources.has(node.id) ? 'D' : record.evidenceAudit.previousRoute === 'current_data' ? 'B' : record.evidenceAudit.previousRoute === 'modeled' ? 'D' : 'C');
  const assessments = override ? { human: override.human, ecosystem: override.ecosystem } : {
    human: domains.includes('human') ? {
      severity: peopleSeverity(node, record, facts), reach: peopleReach(node, facts), persistence: persistence(node, record, facts, 'human'),
    } : null,
    ecosystem: domains.includes('ecosystem') ? {
      severity: natureSeverity(node, record, facts), reach: natureExtent(node, facts), persistence: persistence(node, record, facts, 'ecosystem'),
    } : null,
  };
  if (!override && ['C', 'D'].includes(confidence)) {
    for (const assessment of Object.values(assessments)) {
      if (!assessment) continue;
      for (const axis of Object.values(assessment)) {
        if (!axis.sourceAnchored && axis.lower === axis.central && axis.central === axis.upper) {
          axis.lower = clamp(axis.central - 1);
          axis.upper = clamp(axis.central + 1);
          axis.basis += ' The exact source value still requires a proxy conversion to the TULIP anchor, so the structured bound spans one adjacent level.';
        }
      }
    }
  }
  const registryYear = Number(record.evidenceAudit.sourceAsOf.match(/(?:19|20)\d{2}/)?.[0] ?? 0);
  const supplementYears = certaintySupplements.sources
    .filter(source => source.admittedUses?.[node.id]?.length)
    .map(source => Number(source.publicationDate?.match(/(?:19|20)\d{2}/)?.[0] ?? 0));
  const latestCompatibleEvidenceYear = override?.latestCompatibleEvidenceYear ?? Math.max(registryYear, ...supplementYears);
  return {
    nodeId: node.id, domains, confidence, assessments, domainScopeRule,
    reviewMode: override ? 'detailed_evidence_review' : 'blind_structured_reclassification',
    reviewEvidence: override?.reviewEvidence ?? record.evidenceReferences.map(reference => ({ id: reference.id, url: reference.url, checkedOn: 'repository_evidence_registry_2026-09-22' })),
    finding: override?.finding ?? 'The axes were reclassified from source-native observations and authored consequence boundaries without reading the first-pass value.',
    latestCompatibleEvidenceYear,
    oldEvidenceOpen: latestCompatibleEvidenceYear < 2021,
    sourceAgeFinding: latestCompatibleEvidenceYear < 2021
      ? `The newest compatible evidence ends in ${latestCompatibleEvidenceYear || record.evidenceAudit.sourceAsOf}; the grade remains numerical with confidence and bounds, but source refresh remains open.`
      : `The newest compatible admitted evidence is dated ${latestCompatibleEvidenceYear}.`,
  };
}

function componentFromReview(node, record, dimension, assessment, applicable, confidence) {
  const supplementalEvidenceReferences = certaintySupplements.sources
    .filter(source => source.admittedUses?.[node.id]?.length)
    .map(source => source.id);
  const evidenceReferences = [...new Set([
    ...record.evidenceReferences.map(reference => reference.id),
    ...supplementalEvidenceReferences,
  ])];
  if (!applicable) return {
    lower: axes([0, 0, 0]), central: axes([0, 0, 0]), upper: axes([0, 0, 0]), confidence: confidence === 'D' ? 'C' : confidence, evidenceReferences,
    attribution: `The reviewed boundary for ${node.name} contains no direct ${dimension} terminal consequence.`,
    aggregation: 'The excluded domain is structurally outside the node boundary and is not entered as low harm.',
    overlapReview: 'Connected downstream nodes are not copied into this node to fill the excluded domain.',
    systemEffectsNote: 'Indirect effects remain visible through graph relationships and do not alter structural applicability.',
    structuralZero: true, structuralZeroReason: `Second-pass review confines this node to ${dimension === 'human' ? 'ecosystem' : 'human'} consequences.`,
  };
  const values = ['severity', 'reach', 'persistence'];
  const component = {
    lower: Object.fromEntries(values.map(key => [key, assessment[key].lower])),
    central: Object.fromEntries(values.map(key => [key, assessment[key].central])),
    upper: Object.fromEntries(values.map(key => [key, assessment[key].upper])),
    confidence, evidenceReferences,
    attribution: values.map(key => `${key}: ${assessment[key].basis}`).join(' '),
    aggregation: 'The review uses terminal consequences once and does not add the historical record, related nodes or repeated observations to the current burden.',
    overlapReview: 'The node boundary was checked against connected causes and outcomes; their scores are alternative views and are not inputs here.',
    systemEffectsNote: 'Only evidenced terminal consequences enter the three axes. Plausible unquantified cascades remain outside the number.',
    structuralZero: false,
  };
  if (confidence === 'D') {
    const analogueNodeIds = nearestAnalogues(node, registry.records);
    assert(analogueNodeIds.length, `${node.id}: family fallback needs analogues`);
    component.familyFallback = {
      familyId: `${node.sphere ?? 'cross_domain'}_evidence_family`, analogueNodeIds,
      rationale: `Node-specific current evidence is incomplete. The structured axis levels are checked against ${analogueNodeIds.join(' and ')}, then kept node-specific through its authored reach and persistence.`,
    };
  }
  return component;
}

const blindReviews = new Map();
for (const nodeId of reviewIds) {
  const node = nodesById.get(nodeId);
  const record = registry.records[nodeId];
  assert(node && record, nodeId);
  blindReviews.set(nodeId, blindReview(node, record));
}

const reviewedRows = [];
for (const nodeId of reviewIds) {
  const node = nodesById.get(nodeId);
  const record = registry.records[nodeId];
  const blind = blindReviews.get(nodeId);
  const prior = firstPassById.get(nodeId);
  const blindCandidate = structuredClone(prior.candidate);
  if (detailedOverrides[nodeId]?.currentWindow) blindCandidate.currentWindow = structuredClone(detailedOverrides[nodeId].currentWindow);
  if (detailedOverrides[nodeId]?.referenceBasis) blindCandidate.referenceBasis = structuredClone(detailedOverrides[nodeId].referenceBasis);
  if (detailedOverrides[nodeId]?.history) blindCandidate.history = structuredClone(detailedOverrides[nodeId].history);
  if (detailedOverrides[nodeId]?.outlook) blindCandidate.outlook = structuredClone(detailedOverrides[nodeId].outlook);
  blindCandidate.applicableDomains = blind.domains;
  blindCandidate.components = {
    human: componentFromReview(node, record, 'human', blind.assessments.human, blind.domains.includes('human'), blind.confidence),
    ecosystem: componentFromReview(node, record, 'ecosystem', blind.assessments.ecosystem, blind.domains.includes('ecosystem'), blind.confidence),
  };
  blindCandidate.causalAllocation = structuredClone(detailedOverrides[nodeId]?.causalAllocation ?? causalAllocationFor(nodeId));
  blindCandidate.decisionTrace = {
    method: blind.reviewMode,
    blindToFirstPassDuringClassification: true,
    evidenceRules: 'Fixed TULIP people and nature anchors applied to source-native observations; legacy scores, old vectors, graph degree, source count and prior candidate values prohibited. The authored structural domain boundary is preserved unless an explicit direct-domain or detailed evidence review changes it.',
    applicability: `Reviewed applicable domains: ${blind.domains.join(' and ')}.`,
    domainScopeRule: blind.domainScopeRule,
    axisBasis: blind.assessments,
    ...(detailedOverrides[nodeId]?.measurementSemantics ? { measurementSemantics: structuredClone(detailedOverrides[nodeId].measurementSemantics) } : {}),
    reviewEvidence: blind.reviewEvidence,
    sourceAgeFinding: blind.sourceAgeFinding,
    latestCompatibleEvidenceYear: blind.latestCompatibleEvidenceYear,
    firstPassRevealedAfterClassification: true,
  };
  blindCandidate.reviewStatus = 'second_pass_internal_review_complete';
  const admittedSupplements = certaintySupplements.sources.filter(source => source.admittedUses?.[nodeId]?.length);
  if (admittedSupplements.length) blindCandidate.supplementalEvidenceDigest = digest(admittedSupplements);
  const blindResult = evaluateInternalTulipCandidate(node, blindCandidate, { ...policy, sourceDigest: record.sourceDigest });
  assert.equal(blindResult.status, 'internal_candidate', `${nodeId}: ${blindResult.reasons.join(', ')}`);
  const authoredPilot = prior.assessmentMode === 'authored_pilot_first_pass';
  const retainAuthoredPilot = authoredPilot && !detailedOverrides[nodeId];
  const candidate = retainAuthoredPilot ? structuredClone(prior.candidate) : blindCandidate;
  if (retainAuthoredPilot) {
    candidate.decisionTrace = {
      method: 'pilot_evidence_adjudication',
      blindToFirstPassDuringClassification: true,
      evidenceRules: 'The blind pass prohibited legacy scores, old vectors, graph degree, source count and prior candidate values. The authored structural domain boundary was preserved unless an explicit evidence review changed it.',
      domainScopeRule: blind.domainScopeRule,
      blindAxisBasis: blind.assessments,
      blindResult: { value: blindResult.value, grade: blindResult.grade, uncertainty: blindResult.uncertainty, domains: blindCandidate.applicableDomains },
      adjudication: 'The original pilot record contains node-specific, source-authored axis reasoning. The generic blind classifier supplied no more compatible terminal-consequence evidence, so it cannot replace that stronger assessment.',
      reviewEvidence: Object.values(candidate.components).flatMap(component => component.evidenceReferences ?? []),
      sourceAgeFinding: blind.sourceAgeFinding,
      latestCompatibleEvidenceYear: blind.latestCompatibleEvidenceYear,
      firstPassRevealedAfterClassification: true,
    };
    candidate.reviewStatus = 'second_pass_internal_review_complete';
  }
  const result = retainAuthoredPilot ? evaluateInternalTulipCandidate(node, candidate, { ...policy, sourceDigest: record.sourceDigest }) : blindResult;
  assert.equal(result.status, 'internal_candidate', `${nodeId}: ${result.reasons.join(', ')}`);
  const domainChanged = JSON.stringify(prior.candidate.applicableDomains) !== JSON.stringify(blind.domains);
  const gradeChanged = result.grade.letter !== prior.result.grade.letter;
  reviewedRows.push({
    nodeId, name: node.name, reviewMode: retainAuthoredPilot ? 'pilot_evidence_adjudication' : blind.reviewMode, originalPriority: prior.reviewPriority, originalFlags: prior.reviewFlags,
    firstPass: { value: prior.result.value, grade: prior.result.grade, uncertainty: prior.result.uncertainty, domains: prior.candidate.applicableDomains },
    reviewed: { candidate, result }, domainChanged, gradeChanged,
    disposition: gradeChanged || domainChanged ? 'revised' : 'confirmed_after_reclassification',
    finding: retainAuthoredPilot ? 'The blind result was retained in the audit trace, while the source-specific pilot axes were retained through adjudication.' : blind.finding,
    blindComparison: retainAuthoredPilot ? { value: blindResult.value, grade: blindResult.grade, uncertainty: blindResult.uncertainty, domains: blindCandidate.applicableDomains } : null,
    sourceAgeFinding: blind.sourceAgeFinding, oldEvidenceOpen: blind.oldEvidenceOpen,
  });
}

assert.equal(reviewedRows.length, 354);
assert.equal(new Set(reviewedRows.map(row => row.nodeId)).size, 354);
const reviewedById = new Map(reviewedRows.map(row => [row.nodeId, row]));
const currentReviewFlags = review => {
  const flags = ['deterministic_classification'];
  const candidate = review.reviewed.candidate;
  const result = review.reviewed.result;
  const gradeSpan = gradeRankForScore(result.uncertainty.upper) - gradeRankForScore(result.uncertainty.lower);
  if (candidate.applicableDomains.length === 1) flags.push('single_domain_decision');
  if (gradeSpan > 1) flags.push('range_crosses_multiple_bands');
  if (['C', 'D'].includes(result.confidence)) flags.push('structured_or_family_evidence');
  if (review.oldEvidenceOpen) flags.push('evidence_ends_before_2021');
  if (result.grade.letter === 'E' && candidate.decisionTrace.method === 'blind_structured_reclassification') {
    flags.push('automated_extreme_candidate');
  }
  return flags;
};
const combinedIssues = firstPass.issues.map(row => reviewedById.has(row.nodeId)
  ? { ...row, candidate: reviewedById.get(row.nodeId).reviewed.candidate, result: reviewedById.get(row.nodeId).reviewed.result, reviewPriority: 'reviewed', reviewFlags: currentReviewFlags(reviewedById.get(row.nodeId)), secondPassDisposition: reviewedById.get(row.nodeId).disposition }
  : row);
const gradeCounts = Object.fromEntries(['A', 'B', 'C', 'D', 'E'].map(letter => [letter, combinedIssues.filter(row => row.result.grade.letter === letter).length]));
const reviewedGradeCounts = Object.fromEntries(['A', 'B', 'C', 'D', 'E'].map(letter => [letter, reviewedRows.filter(row => row.reviewed.result.grade.letter === letter).length]));
const highRows = reviewedRows.filter(row => row.originalPriority === 'high');
const mediumRows = reviewedRows.filter(row => row.originalPriority === 'medium');
assert.equal(highRows.length, 154);
assert.equal(mediumRows.length, 200);
const countsFor = rows => ({
  reviewed: rows.length,
  detailedEvidenceReviews: rows.filter(row => row.reviewMode === 'detailed_evidence_review').length,
  blindStructuredReclassifications: rows.filter(row => row.reviewMode === 'blind_structured_reclassification').length,
  pilotEvidenceAdjudications: rows.filter(row => row.reviewMode === 'pilot_evidence_adjudication').length,
  revised: rows.filter(row => row.disposition === 'revised').length,
  confirmed: rows.filter(row => row.disposition === 'confirmed_after_reclassification').length,
  gradeChanged: rows.filter(row => row.gradeChanged).length,
  domainChanged: rows.filter(row => row.domainChanged).length,
  olderEvidenceStillOpen: rows.filter(row => row.oldEvidenceOpen).length,
});
const allCounts = countsFor(reviewedRows);
const highCounts = countsFor(highRows);
const mediumCounts = countsFor(mediumRows);
const summary = {
  version: firstPass.version,
  reviewVersion: 'tulip_internal_catalogue_review_2026_09_27_v131',
  status: 'all_issue_nodes_internal_second_pass_complete',
  reviewedOn: '2026-09-27',
  counts: {
    allIssueNodesReviewed: allCounts.reviewed,
    highPriorityReviewed: highCounts.reviewed,
    mediumPriorityReviewed: mediumCounts.reviewed,
    detailedEvidenceReviews: allCounts.detailedEvidenceReviews,
    blindStructuredReclassifications: allCounts.blindStructuredReclassifications,
    pilotEvidenceAdjudications: allCounts.pilotEvidenceAdjudications,
    revised: allCounts.revised,
    confirmed: allCounts.confirmed,
    gradeChanged: allCounts.gradeChanged,
    domainChanged: allCounts.domainChanged,
    olderEvidenceStillOpen: allCounts.olderEvidenceStillOpen,
    remainingSecondPass: 0,
  },
  highPriorityCounts: highCounts,
  mediumPriorityCounts: mediumCounts,
  reviewedGradeCounts,
  combinedCatalogueGradeCounts: gradeCounts,
  productionRatingsEnabled: 0,
};
const reviewDigest = digest({ summary, reviewedRows });
const highPrioritySummary = {
  ...summary,
  status: 'high_priority_internal_second_pass_complete',
  counts: { ...highCounts, highPriorityReviewed: highCounts.reviewed, remainingMediumPriority: 0 },
  reviewedGradeCounts: Object.fromEntries(['A', 'B', 'C', 'D', 'E'].map(letter => [letter, highRows.filter(row => row.reviewed.result.grade.letter === letter).length])),
};
const highPriorityDigest = digest({ summary: highPrioritySummary, reviewedRows: highRows });
const mediumPrioritySummary = {
  ...summary,
  status: 'medium_priority_internal_second_pass_complete',
  counts: { ...mediumCounts, mediumPriorityReviewed: mediumCounts.reviewed, remainingSecondPass: 0 },
  reviewedGradeCounts: Object.fromEntries(['A', 'B', 'C', 'D', 'E'].map(letter => [letter, mediumRows.filter(row => row.reviewed.result.grade.letter === letter).length])),
};
const mediumPriorityDigest = digest({ summary: mediumPrioritySummary, reviewedRows: mediumRows });

await writeFile(resolve(outDir, 'internal-high-priority-second-pass.json'), JSON.stringify({ ...highPrioritySummary, reviewDigest: highPriorityDigest, reviews: highRows }, null, 2) + '\n');
await writeFile(resolve(outDir, 'internal-medium-priority-second-pass.json'), JSON.stringify({ ...mediumPrioritySummary, reviewDigest: mediumPriorityDigest, reviews: mediumRows }, null, 2) + '\n');
await writeFile(resolve(outDir, 'internal-all-node-second-pass.json'), JSON.stringify({ ...summary, reviewDigest, reviews: reviewedRows }, null, 2) + '\n');
await writeFile(resolve(outDir, 'internal-reviewed-catalogue-candidates.json'), JSON.stringify({ ...firstPass, status: 'all_issue_nodes_second_pass_reviewed', gradeCounts, catalogueReview: { version: summary.reviewVersion, reviewDigest, counts: summary.counts }, issues: combinedIssues }, null, 2) + '\n');
await writeFile(resolve(outDir, 'internal-assessment-progress.json'), JSON.stringify({
  ...summary, catalogueNodes: 381, issueNodes: 354, responseNodes: 27,
  issueNodesAwaitingFirstPass: 0, nodeReviewsCompleted: reviewedRows.length,
  issueNodesAwaitingSecondPass: 0,
}, null, 2) + '\n');

const csvCell = value => `"${String(value ?? '').replaceAll('"', '""')}"`;
const csvFor = reviewRows => [[
  'Node ID', 'Node', 'Disposition', 'Review mode', 'First value', 'First grade', 'Reviewed value', 'Reviewed grade',
  'Reviewed low', 'Reviewed high', 'Confidence', 'First domains', 'Reviewed domains', 'Grade changed', 'Domain changed', 'Finding', 'Source-age finding',
], ...reviewRows.map(row => [
  row.nodeId, row.name, row.disposition, row.reviewMode, row.firstPass.value, row.firstPass.grade.letter,
  row.reviewed.result.value, row.reviewed.result.grade.letter, row.reviewed.result.uncertainty.lower,
  row.reviewed.result.uncertainty.upper, row.reviewed.result.confidence, row.firstPass.domains.join('+'),
  row.reviewed.candidate.applicableDomains.join('+'), row.gradeChanged, row.domainChanged, row.finding, row.sourceAgeFinding,
])];
const writeCsv = (name, reviewRows) => writeFile(resolve(outDir, name), csvFor(reviewRows).map(row => row.map(csvCell).join(',')).join('\n') + '\n');
await writeCsv('internal-high-priority-review-summary.csv', highRows);
await writeCsv('internal-medium-priority-review-summary.csv', mediumRows);
await writeCsv('internal-all-node-review-summary.csv', reviewedRows);

const detailedLines = highRows.filter(row => row.reviewMode === 'detailed_evidence_review').map(row =>
  `- **${row.name}: ${row.firstPass.grade.letter} ${row.firstPass.value} → ${row.reviewed.result.grade.letter} ${row.reviewed.result.value}.** ${row.finding}`
).join('\n');
const highMarkdown = `# TULIP high-priority internal review\n\nStatus: **second pass complete for all ${highCounts.reviewed} high-priority nodes**. The 200 medium-priority candidates have now also completed the same review. No candidate is enabled in production.\n\n## What changed\n\n- Revised grades or domain boundaries: ${highCounts.revised}\n- Confirmed after blind reclassification: ${highCounts.confirmed}\n- Grades changed: ${highCounts.gradeChanged}\n- Domain boundaries changed: ${highCounts.domainChanged}\n- Older evidence still requiring a source refresh: ${highCounts.olderEvidenceStillOpen}\n- Reviewed grade distribution: ${Object.entries(highPrioritySummary.reviewedGradeCounts).map(([grade, count]) => `${grade} ${count}`).join(', ')}\n\nThe second pass classified the evidence before revealing the first-pass value. It used source-native observations and the fixed TULIP anchors. It prohibited legacy scores, vectors, graph degree, source counts and the prior candidate value. Source age affects confidence and the research queue, never whether a node receives a numerical candidate.\n\n## Detailed source reviews\n\n${detailedLines}\n\n## Remaining limitation\n\nThis is a reproducible internal review, not an external independent review. For ${highCounts.olderEvidenceStillOpen} reviewed nodes, the repository's newest compatible evidence still ends before 2021. Their numerical candidates remain visible internally, with that source-age finding attached.\n`;
const allMarkdown = `# TULIP full catalogue internal review\n\nStatus: **second pass complete for all 354 issue nodes**. The 27 response nodes remain outside danger scoring. No candidate is enabled in production.\n\n## Coverage and changes\n\n- High-priority nodes reviewed: ${highCounts.reviewed}\n- Medium-priority nodes reviewed: ${mediumCounts.reviewed}\n- Detailed evidence reviews: ${allCounts.detailedEvidenceReviews}\n- Source-specific pilot adjudications: ${allCounts.pilotEvidenceAdjudications}\n- Blind structured reclassifications: ${allCounts.blindStructuredReclassifications}\n- Revised grades or domain boundaries: ${allCounts.revised}\n- Confirmed after blind reclassification or adjudication: ${allCounts.confirmed}\n- Grades changed: ${allCounts.gradeChanged}\n- Domain boundaries changed: ${allCounts.domainChanged}\n- Older evidence still requiring a source refresh: ${allCounts.olderEvidenceStillOpen}\n- Final candidate distribution: ${Object.entries(gradeCounts).map(([grade, count]) => `${grade} ${count}`).join(', ')}\n\nEvery blind classification was completed before revealing its first-pass value. The review used source-native observations and the fixed TULIP anchors. Legacy scores, vectors, graph degree, source counts and prior candidate values were prohibited. For the ${allCounts.pilotEvidenceAdjudications} source-specific pilot adjudications, the blind result remains in the audit trace and the more detailed authored assessment wins when the generic classifier provides no stronger evidence. The absence of A candidates remains a calibration finding and is not corrected by forcing nodes into a target distribution.\n\n## Internal status\n\nAll issue nodes now have both a first-pass candidate and a second-pass internal review. Source age is recorded separately from severity, so every issue retains a numerical candidate. The audited candidates feed the shared local product registry; production deployment remains a separate release step.\n`;
await writeFile(resolve(outDir, 'internal-high-priority-review-report.md'), highMarkdown);
await writeFile(resolve(outDir, 'internal-all-node-review-report.md'), allMarkdown);
console.log(JSON.stringify({ ...summary, reviewDigest }, null, 2));
